begin read only; set local search_path=pg_catalog; with target as (select p.* from auth.users u join public.profiles p on p.id=u.id where encode(sha256(convert_to(lower(u.email),'UTF8')),'hex')='78517e097a62a504568d89ea98e37c754446634cd03663e9edb9a6d5be5bab5d') select jsonb_build_object('matched_account',count(*),'target_active',bool_and(t.account_status='active'),'profile_hash_except_update_time',min(md5((to_jsonb(t)-'updated_at')::text)),'security_version',(select max(security_version) from mushavo_email_auth.account_state where user_id in(select id from target)),'active_devices',(select count(*) from mushavo_email_auth.devices d where d.user_id in(select id from target) and d.revoked_at is null and d.expires_at>now()),'ready_challenges',(select count(*) from mushavo_email_auth.challenges c where c.user_id in(select id from target) and c.state in('pending_delivery','ready')),'session_proofs',(select count(*) from mushavo_email_auth.session_proofs s where s.user_id in(select id from target)),'remaining_CI_sessions',(select count(*) from auth.sessions where user_agent in ('Mushavo-Staging-Runner/42355118392/1','Mushavo-Staging-Runner/42355292667/1')),'remaining_compensation_sessions',(select count(*) from auth.sessions where user_agent='Mushavo-Account-Suspension-Compensation/20261107'),'normal_queue_rows',(select count(*) from public.notification_outbox),'admin_queue_rows',(select count(*) from public.admin_notification_outbox),'fixture_suspended',(select status='suspended' from public.budget_workspaces where name='audit-batch-x-receipt-d7be160c2026'),'catalog_matches',(select catalog_sha256=mushavo_email_install.catalog_identity() and mode='ACTIVE' and target_project='dczlddwbtgvfdujgcitb' from mushavo_email_install.rollout_control where singleton)) as readback from target t; rollback;
